src={s['id']:s for pg in d['pages'] for s in pg['paragraphs']}
assert [pg['printed_page'] for pg in d['pages']]==list(range(409,419))
assert len(src)==sum(len(pg['paragraphs']) for pg in d['pages'])
assert set(src)=={sid for u in d['units'] for sid in u['source_ids']}
for s in src.values():assert s['sha256']==hashlib.sha256(s['ar'].encode()).hexdigest()
for u in d['units']:
 assert u['ar']==' '.join(src[sid]['ar'] for sid in u['source_ids'])
